import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 4

def design(feats):
    # Find features with strong association to outcome
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue
        x = feats.x[:, i]
        y = feats.y
        mean_diff = np.mean(x[y==1]) - np.mean(x[y==0])
        t_stat, _ = stats.ttest_ind(x[y==1], x[y==0], equal_var=False)
        effects.append((fid, abs(mean_diff), abs(t_stat)))

    effects.sort(key=lambda x: x[2], reverse=True)

    # Select top features for potential drivers
    candidates = [f for f, _, _ in effects[:20]]

    # Check for correlated pairs and remove near-duplicates
    pairs = []
    corr_pairs = set()
    for i in range(len(candidates)):
        for j in range(i+1, len(candidates)):
            fid1, fid2 = candidates[i], candidates[j]
            idx1, idx2 = feats.column(fid1), feats.column(fid2)
            corr = np.corrcoef(feats.x[:, idx1], feats.x[:, idx2])[0, 1]
            if abs(corr) >= 0.6:
                corr_pairs.add((min(fid1, fid2), max(fid1, fid2)))

    # Remove one from each highly correlated pair
    filtered_candidates = []
    used = set()
    for fid in candidates:
        if any(fid in pair for pair in corr_pairs):
            if not any(pair[0] == fid or pair[1] == fid for pair in corr_pairs if pair[0] in used or pair[1] in used):
                filtered_candidates.append(fid)
                used.add(fid)
        else:
            filtered_candidates.append(fid)
            used.add(fid)

    # Try to find interaction terms
    products = []
    for i, fid1 in enumerate(filtered_candidates[:10]):
        for j, fid2 in enumerate(filtered_candidates[:10]):
            if i < j:
                idx1, idx2 = feats.column(fid1), feats.column(fid2)
                prod = feats.x[:, idx1] * feats.x[:, idx2]
                t_stat, _ = stats.ttest_ind(prod[feats.y==1], prod[feats.y==0], equal_var=False)
                if abs(t_stat) > 3.0:
                    products.append((fid1, fid2))

    # If we have interactions, use those as drivers
    if products:
        drivers = [p[0] for p in products[:MAX_DRIVERS]]
        return Design(
            drivers=tuple(drivers),
            columns=tuple([p[0] for p in products[:MAX_DRIVERS]] + [p[1] for p in products[:MAX_DRIVERS]]),
            products=tuple(products[:MAX_DRIVERS]),
            loadings={}
        )

    # Otherwise, select top features by effect size
    drivers = [f for f, _, _ in effects[:MAX_DRIVERS]]
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Return the strongest features as drivers and their corresponding columns
    columns = tuple(drivers)
    return Design(
        drivers=tuple(drivers),
        columns=columns,
        products=(),
        loadings={}
    )

